import{_ as n,h as i,i as e,c as o,v as t,p as h,x as r,m as s,e as p,S as m}from"./chunks/framework.Dvtg8yj2.js";const f=JSON.parse('{"title":"并行 Attention-FFN","description":"","frontmatter":{"title":"并行 Attention-FFN","date":"2026-09-03T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/parallel-attn-ffn.md","filePath":"llm/parallel-attn-ffn.md","lastUpdated":1788454257000}'),d={name:"llm/parallel-attn-ffn.md"};function F(N,a,P,E,c,A){const l=i("Mermaid");return e(),o("div",null,[a[1]||(a[1]=t('<h1 id="并行-attention-ffn" tabindex="-1">并行 Attention-FFN <a class="header-anchor" href="#并行-attention-ffn" aria-label="Permalink to &quot;并行 Attention-FFN&quot;">​</a></h1><div class="epigraph"><p>注意力与前馈不再一前一后写同一条残差，而是从同一归一化输入并行算出，再一起加回主干。</p><footer>—— Wang 与 Komatsuzaki，GPT-J，2021；Chowdhery 等，PaLM，2022</footer></div><p>标准 Pre-LN 块是两条串行残差：先注意力写回 \\(x\\)，再前馈读这个更新后的状态。GPT-J 把两步改成从同一个 \\(\\mathrm{LN}(x)\\) 并行计算，相加后一次写回。PaLM 采用同一结构，并报告在其尺度上更省计算。并行不减少注意力的二次项，也不改变 FFN 宽度公式；它减少的是层内的串行深度，并让 FFN 看不到本层注意力的输出。参数效率与表示深度因此一起被改写。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>串行块为</p> \\[h = x + \\mathrm{Attn}(\\mathrm{LN}(x)),\\qquad y = h + \\mathrm{FFN}(\\mathrm{LN}(h)) \\]<p>一层之内有两次残差加法、两次归一化输入，且 FFN 的输入依赖本层注意力已经写过的 \\(h\\)。这在表示上更「深」：同一层就能完成「先混合上下文、再逐位置非线性」。代价是串行：必须等注意力结束才能开始 FFN，流水线与算子融合的空隙更大；有效深度随层数的增长也更快，深层训练更吃残差稳定性。</p><p>并行块问：若强制</p> \\[y = x + \\mathrm{Attn}(\\mathrm{LN}(x)) + \\mathrm{FFN}(\\mathrm{LN}(x)) \\]<p>能否用更浅的层内依赖换吞吐，并用同样的模块在大宽度下把参数用在并行分支而不是串行组合上？GPT-J 给出可工作的实现，PaLM 在更大尺度上把它当成默认块。<span class="marginnote">并行之后，FFN 不再是「注意力输出的逐位置 MLP」，而是「与注意力共享入口的另一条残差分支」。层的算法含义变了：混合与非线性是同时发生的摄动，下一层才看见二者之和。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>实现上对 \\(x\\) 做一次归一化（LayerNorm 或 RMSNorm），得到 \\(\\tilde x\\)。\\(\\tilde x\\) 同时进入注意力与 FFN。两路输出相加，再加回 \\(x\\)。没有 \\(h\\)，也没有第二次 LN。参数量与串行块接近：投影矩阵集合相同，只是 FFN 不再接到注意力之后的另一份归一化。</p><p>GPT-J-6B 在 2021 年用这一结构训练解码器。PaLM 在 2022 年明确写明采用与 GPT-J 类似的并行公式，作为其 Transformer 变体的一部分。二者都是 Pre-LN 家族：归一化在分支前，主干是未归一的求和。</p>',13)),(e(),h(m,null,{default:r(()=>[p(l,{id:"mermaid-33",class:"mermaid",graph:"flowchart%20TD%0A%20%20X%5B%22%E6%AE%8B%E5%B7%AE%E4%B8%BB%E5%B9%B2%20x%22%5D%20--%3E%20LN%5B%22%E4%B8%80%E6%AC%A1%E5%BD%92%E4%B8%80%E5%8C%96%22%5D%0A%20%20LN%20--%3E%20AT%5B%22%E6%B3%A8%E6%84%8F%E5%8A%9B%22%5D%0A%20%20LN%20--%3E%20FF%5B%22%E5%89%8D%E9%A6%88%E7%BD%91%E7%BB%9C%22%5D%0A%20%20AT%20--%3E%20S%5B%22%E4%B8%A4%E8%B7%AF%E8%BE%93%E5%87%BA%E7%9B%B8%E5%8A%A0%22%5D%0A%20%20FF%20--%3E%20S%0A%20%20X%20--%3E%20Y%5B%22%E5%8A%A0%E5%9B%9E%E4%B8%BB%E5%B9%B2%22%5D%0A%20%20S%20--%3E%20Y%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>方法不包含新的注意力定义：仍可以是多头、多查询或分组查询；并行只规定与 FFN 的接线。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><h3 id="串行块与并行块" tabindex="-1">串行块与并行块 <a class="header-anchor" href="#串行块与并行块" aria-label="Permalink to &quot;串行块与并行块&quot;">​</a></h3><p>串行块的 FFN 看到的是已经掺入本层上下文的 \\(h\\)。非线性可以立即作用于「刚读完的邻居」。并行块的 FFN 只看到 \\(\\mathrm{LN}(x)\\)，与注意力读的是同一份过去状态。本层注意力写出的信息，要到下一层才会被 FFN 处理。等价地说，把原来「层内深度 2」的组合拆成「宽度 2」的加法。表示能力上，需要更多层才能模拟「先读后写再非线性」的电路；层数相同时，并行模型更浅。</p><p>加法是线性的，两路之间没有门控。若注意力输出与 FFN 输出在初始化时方差相近，主干一步收到双倍摄动，这与 DeepNorm 要控制的 \\(G\\) 的尺度同类。实践中靠 Pre-LN、学习率与可能的残差缩放来收。</p><h3 id="参数效率与深度" tabindex="-1">参数效率与深度 <a class="header-anchor" href="#参数效率与深度" aria-label="Permalink to &quot;参数效率与深度&quot;">​</a></h3><p>参数量几乎不变，因为没有删除矩阵。效率改的是「每一参数所在的深度位置」。串行时 FFN 的参数作用在更深的中间表示上；并行时两套参数作用在同一深度。PaLM 报告并行在其训练体系里计算效率更高：注意力与 FFN 可同时占计算单元，减少气泡。这是系统效率，不是参数更少。若以「同样层数、同样宽度」比质量，串行有时略好，因为层内更深；若以墙钟或流水线利用率比，并行常常胜。</p><p><span class="marginnote">不要把并行理解成 MoE。MoE 是多专家之间的稀疏路由；并行是注意力与单个 FFN 的稠密双分支。专家并行改的是宽度与稀疏，这块改的是层内串行度。二者可以叠，但机制无关。</span></p><h3 id="gpt-j-与-palm-的实践" tabindex="-1">GPT-J 与 PaLM 的实践 <a class="header-anchor" href="#gpt-j-与-palm-的实践" aria-label="Permalink to &quot;GPT-J 与 PaLM 的实践&quot;">​</a></h3><p>GPT-J 证明六亿到六十亿参数的解码器可以在并行块上稳定训练，且实现简单。PaLM 把同一选择带到大得多的稠密 Transformer，并与其它变体一起写进模型描述，而不是当成消融里的边角。后续不少开源模型仍用串行 Pre-LN，说明并行不是新的唯一正确块，而是在算力调度与深度之间的显式取舍。选用时应看并行硬件能否真的重叠 Attn 与 FFN；若内核仍然串行发射，则只剩表示变浅的缺点，没有吞吐优点。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>并行块与 Post-LN 组合时要重新定义「加在哪里再 LN」，没有唯一标准实现，多数讨论默认 Pre-LN。出口处仍需一次归一化再进词头。与 YaRN、ALiBi 无关：位置在注意力内部处理，接线在块级。</p><p>梯度检查点若只保存 \\(x\\) 与 \\(\\tilde x\\)，反向时两路可分别重算，比串行少一段依赖。但显存峰值可能更高，因为两路激活同时存在。宽度很大时，这比「层内更浅」更先碰到。</p><p><span class="marginnote">质量对比必须固定层数与宽度。用更少层的并行模型去打更多层的串行模型，分不清是接线的效果还是深度的效果。PaLM 的「更高效」是在其训练栈上的计算效率，不是一条与硬件无关的定理。</span></p><h3 id="何时保持串行" tabindex="-1">何时保持串行 <a class="header-anchor" href="#何时保持串行" aria-label="Permalink to &quot;何时保持串行&quot;">​</a></h3><p>小模型、层数本就不多、或内核无法重叠两路计算时，串行更直观，也保留「一层内先混合后非线性」的电路。大模型、流水线气泡明显、且实现能真正并行发射时，再考虑 GPT-J / PaLM 式接线。改接线要重训，不能把串行检查点的 FFN 权重接到并行入口上指望对齐。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>并行 Attention-FFN 从同一归一化输入同时算两路，一次加回残差主干。</li><li>层内串行深度变浅，本层 FFN 看不到本层注意力输出。</li><li>参数量与模块集合基本不变，改变的是参数所在深度与计算重叠。</li><li>GPT-J 给出实用实现，PaLM 在大尺度上采用并强调计算效率。</li><li>若硬件不能重叠两路，并行只剩表示变浅，没有系统收益。</li><li>与 MoE、与位置编码、与 LN 用 RMS 还是 Layer 都可组合，但要单独调残差尺度。</li><li>出处：Wang 与 Komatsuzaki，GPT-J，2021；Chowdhery 等，<em>PaLM: Scaling Language Modeling with Pathways</em>，2022；块级归一化背景见 Xiong 等（2020）。</li></ul>',18))])}const L=n(d,[["render",F]]);export{f as __pageData,L as default};
